"sciences.21":["Évolution",[["En quelle année Darwin publie-t-il De l'origine des espèces ?","1859","1789","1905","1953"],["Qu'est-ce que la sélection naturelle ?","Les mieux adaptés survivent et transmettent leurs caractéristiques","Les plus forts tuent les autres","Un choix volontaire des espèces","Un tri fait par les humains"],["L'humain descend-il du singe ?","Non, ils ont un ancêtre commun","Oui, du chimpanzé","Oui, du gorille","Non, d'aucun ancêtre commun"],["Quel exemple d'évolution observe-t-on en direct ?","Les bactéries résistantes aux antibiotiques","La taille des girafes","La couleur du ciel","La vitesse des voitures"]]],
